def _sha256(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


SYSTEM_MESSAGE_SHA256 = _sha256(SYSTEM_MESSAGE)
STRUCTURED_OUTPUT_SCHEMA_SHA256 = _sha256(
    json.dumps(STRUCTURED_OUTPUT_SCHEMA, sort_keys=True, separators=(",", ":")))


def build_user_message(*, transcript_text: str, transcript_id: str, meeting_id: str,
                       subject: str, scheduled_start: str, created_datetime: str,
                       start_difference_minutes, start_status: str,
                       scheduled_end: str, end_datetime: str,
                       end_difference_minutes, end_status: str,
                       duration_minutes, ksb_framework: str = "") -> str:
    """
    Reproduce the legacy agent `text` template exactly, including its blank
    lines and the space before the colon on the difference/status fields.

    Legacy used `?? ""` and `|| ""`, so a missing value renders as an empty
    string, never as "None".
    """
    def value(raw):
        return "" if raw is None else str(raw)

    return (
        "TRANSCRIPT:\n"
        f"{value(transcript_text)}\n"
        "\n"
        "METADATA:\n"
        f"transcriptId: {value(transcript_id)}\n"
        f"meetingId: {value(meeting_id)}\n"
        "\n"
        "\n"
        "\n"
        f"subject: {value(subject)}\n"
        "\n"
        f"scheduledStartDateTime: {value(scheduled_start)}\n"
        f"createdDateTime: {value(created_datetime)}\n"
        f"startDifferenceMinutes : {value(start_difference_minutes)}\n"
        f"startStatus : {value(start_status)}\n"
        "\n"
        f"scheduledEndDateTime: {value(scheduled_end)}\n"
        f"endDateTime: {value(end_datetime)}\n"
        f"endDifferenceMinutes : {value(end_difference_minutes)}\n"
        f"endStatus : {value(end_status)}\n"
        "\n"
        f"durationMinutes: {value(duration_minutes)}\n"
        "\n"
        "KSB_Framework (optional):\n"
        f"{value(ksb_framework)}"
    )


def prompt_sha256(*, model: str) -> str:
    """
    Hash of everything that defines one prompt contract: the prompt version,
    the system message, the structured schema and the model identity.
    """
    return _sha256("\0".join([
        PROMPT_VERSION, SYSTEM_MESSAGE_SHA256,
        STRUCTURED_SCHEMA_VERSION, STRUCTURED_OUTPUT_SCHEMA_SHA256, model,
    ]))
